#!/bin/sh
# Builds the atg_cpu test programs of sim/tb/cpu/ into $readmemh images
# (one 32-bit word per line): NAME.imem.hex (.text, IMEM at 0) and
# NAME.dmem.hex (.data, DMEM at 0x0001_0000).  rv32i.S and rv32m.S are
# generated by gen.py first.  cpu_*.S are atg_cpu images (padded to the
# default IMEM/DMEM sizes).  The images are committed, so sim/run.sh
# does not need a compiler; run this after changing a program.
#   tools/cpu-tests.sh        (CLANG_BIN=dir with clang, ld.lld, llvm-objcopy)
# Uses the shared LLVM read-only; intermediate files go to build/cpu-tests/.
# Copyright (C) 2026 Awe Morris; SPDX-License-Identifier: Zlib
set -eu
root=$(cd "$(dirname -- "$0")/.." && pwd)
bin=${CLANG_BIN:-/home/awe/zedBSD-claude1/build/llvm/bin}
src=$root/sim/tb/cpu
out=$root/build/cpu-tests
mkdir -p "$out"
timeout 60 python3 -I "$src/gen.py" "$src"
for s in "$src"/*.S; do
	n=$(basename "$s" .S)
	timeout 60 "$bin/clang" --target=riscv32-unknown-elf -march=rv32im -mabi=ilp32 \
		-mno-relax -c "$s" -o "$out/$n.o"
	timeout 60 "$bin/ld.lld" -T "$src/link.ld" "$out/$n.o" -o "$out/$n.elf"
	for sec in text data; do
		m=imem
		[ "$sec" = data ] && m=dmem
		"$bin/llvm-objcopy" -O binary --only-section=".$sec" "$out/$n.elf" "$out/$n.$m.bin"
		# od prints little-endian words on this host; pad to whole words.
		size=$(wc -c <"$out/$n.$m.bin")
		pad=$(( (4 - size % 4) % 4 ))
		[ "$pad" -gt 0 ] && head -c "$pad" /dev/zero >>"$out/$n.$m.bin"
		od -An -v -tx4 -w4 "$out/$n.$m.bin" | tr -d ' ' >"$src/$n.$m.hex"
		[ -s "$src/$n.$m.hex" ] || echo 00000000 >"$src/$n.$m.hex"
		# cpu_*: atg_cpu's init images, padded to the default sizes (the
		# simulator warns about a short $readmemh file).
		case $n in cpu_*)
			full=8192
			[ "$m" = dmem ] && full=4096
			have=$(wc -l <"$src/$n.$m.hex")
			[ "$have" -lt "$full" ] && yes 00000000 | head -n $((full - have)) >>"$src/$n.$m.hex"
		esac
	done
	echo "cpu-tests: $n $(wc -l <"$src/$n.imem.hex") words"
done
